mapper.select:
SELECT EXISTS (
    SELECT 1
      FROM members
     WHERE id = #{id}
       AND is_deleted IS NOT TRUE
)

mapper.update:
UPDATE members
   SET name       = #{name},
       birth_date = #{birthDate},
       mail       = #{mail}
 WHERE id = #{id}

UPDATE members
   SET is_deleted = true
 WHERE id = #{id}
